{"cards": [{"node_code": "N_253238d4186203d2", "definition": "研究利用无线电、雷达、卫星及自动化系统实现船舶定位、导航与通信的技术体系，涵盖设备原理、航海应用及新兴技术。", "boundary": "本节点聚焦于“电子与自动化”手段在航海中的应用。边界在于区分“传统天文/地文导航”（归入航位测定或航海基础科学）与“电子导航”。若内容涉及通信协议、信号处理或导航算法，归入本节点；若涉及通信设备硬件制造，归入船舶工程。", "includes": ["无线电测向、无线电导航（如LORAN、GPS）及雷达在航海中的具体应用", "自动导航系统（如ECDIS、AIS）的原理与操作", "船舶无线电通信技术及新技术在航海中的应用"], "excludes": ["传统天文导航与地文定位方法（归入航位测定）", "通信与导航设备的机械结构设计与制造工艺（归入船舶工程）"], "sibling_distinctions": [{"other_code": "N_0a2153b9eed35ee9", "rule": "本节点侧重电子、无线电及自动化导航手段；兄弟节点侧重基于天文、地文及推算的传统定位方法。"}, {"other_code": "N_d4995ceafb64dfca", "rule": "本节点侧重导航与通信系统的功能、原理及航海应用；兄弟节点侧重各类航海仪器、用具的构造、性能及维护。"}], "cross_boundary_rule": "若内容涉及导航/通信设备在航海中的具体操作、信号解读或系统集成，主挂载本节点；若涉及设备内部硬件研发、电路设计或制造，主挂载船舶工程。"}, {"node_code": "N_5dcd0bbca21a0d20", "definition": "涵盖航海过程中使用的各类出版物、图表、记录及规范性文本，包括海图、航路指南、航海日志、法规及术语等。", "boundary": "本节点聚焦于“信息载体”与“规范文本”。边界在于区分“资料本身”与“使用资料的技术”。若内容涉及海图绘制、航路指南编写或法规条文，归入本节点；若涉及利用海图进行定位或操纵的具体技术，归入航位测定或船舶操纵技术。", "includes": ["海图、海图作业及航海用表、航海日志", "航路指南、航海星图、天气图等专用图表", "海事法规、航海术语及海事总结等规范性与参考性文本"], "excludes": ["利用海图或指南进行具体定位、导航的操作技术（归入航位测定或船舶导航与通信）", "海事法规的执法、司法实践及事故调查（归入航海技术管理与救助打捞）"], "sibling_distinctions": [{"other_code": "N_0a2153b9eed35ee9", "rule": "本节点收录海图、指南等静态资料及其编制；兄弟节点收录利用这些资料进行动态定位、推算的方法与技术。"}, {"other_code": "N_253238d4186203d2", "rule": "本节点收录航海相关的文本、图表资料；兄弟节点收录电子导航、通信系统及自动化技术。"}], "cross_boundary_rule": "若内容涉及海图、指南的编制、出版或内容解读，主挂载本节点；若涉及利用海图/指南进行实时导航、定位的操作过程，主挂载航位测定或船舶导航与通信。"}, {"node_code": "N_4c709dbaf9b22849", "definition": "研究船舶在水中的运动规律及驾驶操纵方法，涵盖船舶运动性能、锚泊、拖带、避让及特殊条件下的操纵技术。", "boundary": "本节点聚焦于“船舶运动控制”与“驾驶操作”。边界在于区分“操纵技术”与“导航定位”。若内容涉及舵效、惯性、避让动作或锚泊操作，归入本节点；若涉及确定船位、规划航线，归入航位测定或船舶导航与通信。", "includes": ["船舶运动性能（惯性、舵效、旋回等）及锚泊、拖带、顶推技术", "困难、紧急条件下的操纵及特殊操纵问题", "船舶避让操作及领港术"], "excludes": ["船舶船体结构、动力系统设计（归入船舶工程）", "基于电子设备的航线规划与定位技术（归入船舶导航与通信或航位测定）"], "sibling_distinctions": [{"other_code": "N_0a2153b9eed35ee9", "rule": "本节点侧重“如何控制船”（操纵、避让、锚泊）；兄弟节点侧重“船在哪里”（定位、推算）。"}, {"other_code": "N_bebc26e8e12f6ead", "rule": "本节点侧重通用及特定工况下的操纵技术与方法；兄弟节点侧重不同环境条件（如雾、夜、冰区）对航行策略的影响。"}], "cross_boundary_rule": "若内容涉及船舶运动力学、操纵动作、避让规则执行，主挂载本节点；若涉及利用导航设备确定位置或规划航线，主挂载航位测定或船舶导航与通信。"}]}
